<?php
require_once __DIR__.'/../../includes/init.php';require_role('admin');require_once __DIR__.'/../../includes/layout.php';$pdo=db();$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$page=page_number();$lim=12;$w=[];$p=[];if($q!==''){$w[]='(k.plat_nomor LIKE ? OR CAST(t.id_parkir AS CHAR) LIKE ? OR k.pemilik LIKE ?)';array_push($p,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if(in_array($status,['masuk','keluar'],true)){$w[]='t.status=?';$p[]=$status;}try{if($from!==''&&$to!==''){[$a,$b]=valid_date_range($from,$to);$w[]='t.waktu_masuk BETWEEN ? AND ?';array_push($p,$a,$b);}elseif($from!==''||$to!=='')throw new InvalidArgumentException('Isi tanggal mulai dan akhir.');}catch(Throwable $e){$error=$e->getMessage();} $ws=$w?' WHERE '.implode(' AND ',$w):'';$c=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan'.$ws);$c->execute($p);$total=(int)$c->fetchColumn();$s=$pdo->prepare("SELECT t.id_parkir,t.waktu_masuk,t.waktu_keluar,t.status,t.durasi_jam,t.biaya_total,t.tarif_saat_masuk,k.plat_nomor,k.jenis_kendaraan,a.nama_area,u.nama_lengkap AS petugas FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area JOIN tb_user u ON u.id_user=t.id_user$ws ORDER BY t.id_parkir DESC LIMIT $lim OFFSET ".(($page-1)*$lim));$s->execute($p);$rows=$s->fetchAll();render_header('Riwayat Transaksi','transaksi');?>
<div class="page-intro"><div><h2>Seluruh transaksi parkir</h2><p>Cari transaksi berdasarkan plat, nomor transaksi, status, atau tanggal masuk.</p></div></div><?php if(!empty($error)): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><form method="get" class="filter-row"><div class="field" style="min-width:230px"><label>Pencarian</label><input name="q" value="<?= h($q) ?>" placeholder="Plat, pemilik, ID transaksi"></div><div class="field"><label>Status</label><select name="status"><option value="">Semua status</option><option value="masuk" <?= $status==='masuk'?'selected':'' ?>>Sedang parkir</option><option value="keluar" <?= $status==='keluar'?'selected':'' ?>>Selesai</option></select></div><div class="field"><label>Dari tanggal</label><input name="from" type="date" value="<?= h($from) ?>"></div><div class="field"><label>Sampai tanggal</label><input name="to" type="date" value="<?= h($to) ?>"></div><button class="btn btn-primary">Terapkan filter</button><a class="btn btn-secondary" href="<?= h(url('admin/transaksi/index.php')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Plat Nomor</th><th>Area</th><th>Waktu Masuk</th><th>Waktu Keluar</th><th>Status</th><th>Durasi</th><th>Total</th><th>Petugas</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td class="td-main"><?= h($r['plat_nomor']) ?><div class="muted"><?= h(ucfirst($r['jenis_kendaraan'])) ?></div></td><td><?= h($r['nama_area']) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= h(tanggal($r['waktu_keluar'])) ?></td><td><?= status_badge($r['status']) ?></td><td><?= $r['durasi_jam']===null?'-':(int)$r['durasi_jam'].' jam' ?></td><td><?= $r['biaya_total']===null?'-':h(rupiah($r['biaya_total'])) ?></td><td><?= h($r['petugas']) ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="9"><div class="empty-state"><strong>Transaksi tidak ditemukan</strong>Sesuaikan filter pencarian.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $total ?> transaksi ditemukan</span><?= pagination($total,$lim,$page,url('admin/transaksi/index.php?q='.rawurlencode($q).'&status='.rawurlencode($status).'&from='.rawurlencode($from).'&to='.rawurlencode($to))) ?></div></section><?php render_footer(); ?>